[
  {
    "incident": {
      "component": "mongo-analytics-01",
      "category": "Disk Space Exhaustion",
      "status": "firing",
      "summary": "Critical disk usage alert on production MongoDB secondary node with 95% capacity reached."
    },
    "assessment": {
      "urgency": "high",
      "rationale": "Disk usage is at 95% on a production instance. While growth is currently flat, reaching 100% will cause database corruption or service outage."
    },
    "facts": [
      "Alertname: MongoDBDiskSpaceLow",
      "Instance: mongo-analytics-01:9216",
      "Severity: critical",
      "Env: prod",
      "Disk usage: 95%",
      "Filesystem size: 2TiB",
      "Available space: 102GiB",
      "Growth rate: 0GiB/h",
      "Replica set role: secondary",
      "Usage has been flat for 7 days"
    ],
    "missing_context": [
      {
        "item": "Primary node disk status",
        "why": "If the primary is also full, the entire replica set is at risk.",
        "how_to_check": "Check metrics for the primary node in the same replica set."
      },
      {
        "item": "Disk composition",
        "why": "To determine if space is taken by data files, logs, or journal files.",
        "how_to_check": "ssh mongo-analytics-01 'du -sh /var/lib/mongodb/*'"
      },
      {
        "item": "Oplog size and retention",
        "why": "To ensure disk pressure isn't caused by an oversized oplog.",
        "how_to_check": "mongo --eval 'db.getReplicationInfo()'"
      }
    ],
    "immediate_actions": [
      {
        "action": "Check for large log files",
        "purpose": "Identify if non-data files can be safely truncated or rotated.",
        "conditions": "If logs are consuming significant space.",
        "expected_effect": "Immediate reclamation of disk space.",
        "risks": "Loss of historical log data.",
        "requires_approval": false,
        "verify": "df -h",
        "rule_ids": [
          "DISK_CLEANUP_01"
        ]
      },
      {
        "action": "Expand disk volume",
        "purpose": "Increase capacity to prevent outage.",
        "conditions": "If data growth is legitimate and logs are not the cause.",
        "expected_effect": "Increased filesystem capacity.",
        "risks": "Cloud provider cost increase; potential filesystem resize failure.",
        "requires_approval": true,
        "verify": "df -h",
        "rule_ids": [
          "INFRA_EXPANSION_01"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Analyze disk usage distribution",
        "hypothesis": "The space is consumed by the MongoDB data directory rather than logs.",
        "how_to_check": "du -h --max-depth=1 /var/lib/mongodb"
      },
      {
        "step": "Check MongoDB internal metrics",
        "hypothesis": "Large collections or indexes are consuming the space.",
        "how_to_check": "mongo --eval 'db.stats()'"
      }
    ],
    "root_cause_hypotheses": [
      "Natural data growth reaching the capacity of the 2TiB volume.",
      "Unbounded log file growth.",
      "Large temporary files or journal files from heavy write operations."
    ],
    "dangerous_operations": [
      {
        "operation": "Deleting MongoDB data files",
        "why_dangerous": "Will cause immediate database corruption and replica set inconsistency.",
        "rule_id": "DATA_INTEGRITY_01"
      },
      {
        "operation": "Shrinking filesystem",
        "why_dangerous": "Extremely risky and often not supported on live cloud volumes.",
        "rule_id": "FS_RESIZE_01"
      }
    ],
    "applied_expert_rules": [
      "DISK_MONITORING_01",
      "REPLICA_SET_SAFETY_01"
    ],
    "incident_update": "🚨 *Critical Alert*: `mongo-analytics-01` (prod) is at 95% disk usage. Growth is currently flat, but we are investigating if this is data-driven or log-driven. Monitoring primary node status now. #incident-mongodb-disk"
  }
]
